import{z as i,x as l,o as A,c as d,q as r,j as s,D as a,d as t,s as n,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"结构对约化形式","description":"","frontmatter":{"title":"结构对约化形式","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/structural-vs-reduced.md","filePath":"econ/structural-vs-reduced.md","lastUpdated":1791413859000}'),c={name:"econ/structural-vs-reduced.md"};function p(u,E,D,m,C,F){const B=l("Mermaid");return A(),d("div",null,[E[2]||(E[2]=r('<h1 id="结构对约化形式" tabindex="-1">结构对约化形式 <a class="header-anchor" href="#结构对约化形式" aria-label="Permalink to &quot;结构对约化形式&quot;">​</a></h1><div class="epigraph"><p>约化形式是给定制度下的统计关系；结构是偏好、技术与均衡约束。政策一改制度，约化形式可以整张表作废——这正是卢卡斯批判。</p><footer>—— Marschak, Economic Measurements for Policy and Prediction；Lucas, Econometric Policy Evaluation: A Critique, 1976；Heckman 论结构与因果</footer></div><p><a href="/econ/event-study-econ">上一课</a>把公告窗的累积异常写成设计。准实验在支撑内已经能估「这个政策在这个制度里做了什么」。本单元缺口是另一类问题：制度若改成从未发生过的规则，设计没有对照。结构对约化是本课序的第一课；离散选择下一课给出第一个参数化例子。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DiD 估的是观测到的处理对观测到的结果。若要问「若把税率改成从未出现的课表」或「若市场变成伯川德而不是现在的谈判」，潜在结果的支持里没有这些 \\(d\\)。Marschak 的目标：政策评价需要的是对干预稳定的参数（弹性、调价成本、折现），不是简化式斜率。Lucas（1976）：把 \\(C=cY\\) 当结构去模拟新规则，等于假设预期规则不变。缺口不是再骂一次回归，而是划分：哪些问题设计够用，哪些必须进均衡与决策规则。</p><p>Heckman：实验与 IV 识别的是政策不变（或局部不变）的因果效应；外推到新环境要选择模型或一般均衡。两边不是教派。随机化培训实验不自动给出「全国强制培训后的工资」，因为一般均衡工资会动。</p><p><span class="marginnote">约化形式不是贬义词。它是 \\(\\mathbb{E}[Y\\mid Z]\\)。IV 的约化形式除以第一阶段就是 Wald。结构失败时，诚实的约化形式仍是证据；失败的结构不是「因为更深所以更真」。</span></p><p><span class="marginnote">直觉类比：约化形式像「司机踩油门时车往前」的统计规律。一旦换成自动巡航（制度变了），油门踏板的含义整个变了，旧规律作废——卢卡斯批判说的就是：人的行为规则会随规则本身而改变。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写清反事实：是对观测处理赋值的干预（设计），还是对均衡映射的干预（结构）。结构：声明不变对象（\\(u\\)、技术、\\(c_i\\) 的分布），解均衡，用观测矩估参数，再在新政策下重解。识别要另证：观测等价的结构可以给出不同反事实——那是后课 BLP、拍卖的核心。</p>',10)),(A(),s(o,null,{default:a(()=>[n(B,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DES%5B%22%E8%AE%BE%E8%AE%A1%3A%20%E8%A7%82%E6%B5%8B%E6%94%AF%E6%8C%81%E5%86%85%E7%9A%84%20d%22%5D%20--%3E%20RED%5B%22%E7%BA%A6%E5%8C%96%20%2F%20LATE%20%2F%20ATT%22%5D%0A%20%20NEW%5B%22%E4%BB%8E%E6%9C%AA%E5%87%BA%E7%8E%B0%E7%9A%84%E8%A7%84%E5%88%99%22%5D%20--%3E%20STR%5B%22%E7%BB%93%E6%9E%84%3A%20%E9%87%8D%E8%A7%A3%E5%9D%87%E8%A1%A1%22%5D%0A%20%20LUC%5B%22Lucas%3A%20%E7%AE%80%E5%8C%96%E5%BC%8F%E5%90%AB%E6%97%A7%E8%A7%84%E5%88%99%22%5D%20--%3E%20STR%0A%20%20STR%20--%3E%20ID%5B%22%E8%AF%86%E5%88%AB%3A%20%E5%8F%8D%E4%BA%8B%E5%AE%9E%E6%98%AF%E5%90%A6%E8%A2%AB%E7%9F%A9%E9%92%89%E4%BD%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("p",null,"校准与估计：宏观常用校准深层参数再匹配矩；微观产业常用 GMM / MLE。本课不选边，只要求：目标函数对应的矩要能分开要的弹性。",-1)),E[4]||(E[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=e("p",null,"机制是不变性范围。ATE 的不变性是 SUTVA 加赋值；结构的不变性是偏好与技术在新均衡里仍成立。一旦政策改变偏好（习惯养成）或技术（学习），结构也会垮，只是垮的位置不同。约化形式在旧规则的支撑上可以极准，这是 DML 的用武之地。",-1)),(A(),s(o,null,{default:a(()=>[n(B,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E4%B8%AA%E6%94%BF%E7%AD%96%E5%8F%8D%E4%BA%8B%E5%AE%9E%E9%97%AE%E9%A2%98%22%5D%20--%3E%20S1%7B%22%E6%96%B0%E6%94%BF%E7%AD%96%E5%80%BC%E5%9C%A8%E5%8E%86%E5%8F%B2%E6%95%B0%E6%8D%AE%E9%87%8C%E5%87%BA%E7%8E%B0%E8%BF%87%E5%90%97%EF%BC%9F%22%7D%0A%20%20S1%20--%3E%7C%22%E5%87%BA%E7%8E%B0%E8%BF%87%EF%BC%8C%E4%B8%94%E6%9C%89%E5%8F%AF%E6%AF%94%E5%AF%B9%E7%85%A7%22%7C%20D%5B%22%E7%94%A8%E8%AE%BE%E8%AE%A1%EF%BC%9ARCT%20%2F%20DiD%20%2F%20IV%22%5D%0A%20%20D%20--%3E%20D2%5B%22%E5%BE%97%E5%88%B0%E6%94%AF%E6%92%91%E5%86%85%E7%9A%84%20LATE%20%E6%88%96%20ATT%22%5D%0A%20%20S1%20--%3E%7C%22%E4%BB%8E%E6%9C%AA%E5%87%BA%E7%8E%B0%22%7C%20S2%7B%22%E8%83%BD%E5%86%99%E5%87%BA%E4%B8%8D%E5%8F%98%E5%AF%B9%E8%B1%A1%E5%B9%B6%E8%A7%A3%E5%9D%87%E8%A1%A1%E5%90%97%EF%BC%9F%22%7D%0A%20%20S2%20--%3E%7C%22%E8%83%BD%EF%BC%8C%E4%B8%94%E7%9F%A9%E8%B6%B3%E4%BB%A5%E8%AF%86%E5%88%AB%22%7C%20ST%5B%22%E7%BB%93%E6%9E%84%E4%BC%B0%E8%AE%A1%EF%BC%9A%E4%BC%B0%E5%8F%82%E6%95%B0%EF%BC%8C%E9%87%8D%E8%A7%A3%E6%96%B0%E5%9D%87%E8%A1%A1%22%5D%0A%20%20S2%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20HON%5B%22%E8%AF%9A%E5%AE%9E%E6%89%BF%E8%AE%A4%EF%BC%9A%E6%97%A0%E6%B3%95%E5%9B%9E%E7%AD%94%EF%BC%8C%E4%B8%8D%E5%A4%96%E6%8E%A8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">术语翻译：「不变性范围」就是「这条关系在多大范围内继续成立」。ATE 的范围是「同一套赋值规则」，结构参数的范围是「偏好与技术不变」——范围更大，但并非无限：政策若改变了偏好本身，结构同样要垮，只是垮的位置不同。</span></p><p>与<a href="/econ/potential-outcomes">潜在结果</a>：结构给出一整张 \\(Y(d)\\) 对未观测 \\(d\\) 的表，靠的是函数形式与均衡。Rubin 式设计拒绝在支持外填表，除非额外假设。Heckman 的选择模型是中间：用选择方程填部分未观测处理，仍要排除。</p><p><span class="marginnote">Koopmans 的「测量而无理论」警告：没有不变对象，测量的是混合物。反过来，错误的理论会把混合物叫成弹性。检验（过度识别、样本外、制度变化）两边都要。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 DSGE 或 IO 结构写成唯一科学。不重写<a href="/econ/lucas-critique">卢卡斯批判</a>全文，只把它收成单元口号。下一课 logit / probit：在离散选择上第一次看到「效用参数 → 选择概率 → 反事实份额」。BLP 把这套放进价格内生与差异产品均衡。</p><p><span class="marginnote">常见误区：初学者容易把结构模型当「更高级所以更可信」。一个识别失败的结构模型不如一个诚实的 LATE——前者把可疑的假设包装成结论，后者至少清楚自己只回答了哪一个具体问题。</span></p><p>后课默认：设计回答支撑内的因果；支撑外的政策要结构，并单独证明识别。灵活 ML 不能替代均衡。不要用「我们做了因果」拒绝一切反事实价格弹性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>约化形式：给定制度的统计关系；结构：不变对象加均衡。</li><li>新规则不在观测支持内时，设计没有对照。</li><li>Lucas：简化式系数嵌着旧规则。</li><li>识别失败的结构不优于诚实的 LATE。</li><li>出处：Marschak；Lucas 1976；Heckman 结构与因果；Koopmans 测量与理论。</li></ul>',9))])}const f=i(c,[["render",p]]);export{T as __pageData,f as default};
